                      顧客を確認
                    </Link>
                  </div>
                </Card.Content>
              </Card>
            ))
          )}
        </div>
      </div>
    </main>
  );
}

function emptyMessage(total: number): string {
  if (total === 0) return "登録されている顧客はありません。「顧客を追加」から最初の顧客を登録してください。";
  return "条件に一致する顧客が見つかりません。検索条件を変えて確認してください。";
}

